// matnm_test.sio - Tests for dynamic N×M matrix type
//
// T1: Identity * vector = vector
// T2: A * A^-1 = I (3×3)
// T3: det(I) = 1
// T4: QR decomposition: Q * R = A
// T5: Solve Ax=b matches expected solution
//
// All structs/functions inlined (tests cannot import).

// ============================================================================
// HELPERS
// ============================================================================

fn matnm_abs(x: f64) -> f64 {
    if x < 0.0 { 0.0 - x } else { x }
}

fn matnm_sqrt(x: f64) -> f64 with Mut, Div {
    if x <= 0.0 { return 0.0 }
    var scaled = x
    var scale_back = 1.0
    while scaled < 1.0 {
        scaled = scaled * 4.0
        scale_back = scale_back * 2.0
    }
    while scaled > 4.0 {
        scaled = scaled * 0.25
        scale_back = scale_back * 0.5
    }
    var y = 1.5
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    return y / scale_back
}

