    let b: [f64; 8] = [0.2, 0.7, 0.1, 0.8, 0.2, 0.8, 0.1, 0.9]
    let c: [f64; 8] = [0.1, 0.6, 0.1, 0.8, 0.0, 0.3, 0.9, 0.7]
    let d: [f64; 8] = [0.5, 0.7, 0.2, 0.9, 0.1, 0.4, 0.6, 0.3]

